ALTER TABLE tasks ADD COLUMN IF NOT EXISTS rate_limited_at TIMESTAMPTZ;
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS rate_limit_reason TEXT;
COMMENT ON COLUMN tasks.rate_limited_at IS 'Timestamp when task was last rate limited during dispatch';
COMMENT ON COLUMN tasks.rate_limit_reason IS 'Reason for rate limit: concurrent_limit | hourly_limit';

-- =============================================================================
-- Konsolidering: hemsidans (skylandai.se) tabeller in i SCC-projektet
-- Källa: stitch_skyland_ai_operating_system/supabase/migrations/*
--        + voice_calls rekonstruerad från n8n voice-call-ended workflow
-- =============================================================================

CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE IF NOT EXISTS sessions (
    id              uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    session_uuid    uuid        UNIQUE NOT NULL,
    created_at      timestamptz DEFAULT now(),
    last_active_at  timestamptz DEFAULT now(),
    user_agent      text,
    entry_module    text,
    metadata        jsonb       DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS interactions (
    id              uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    session_uuid    uuid        NOT NULL
                                REFERENCES sessions(session_uuid) ON DELETE CASCADE,
    type            text        NOT NULL
                                CHECK (type IN ('voice', 'form', 'view')),
    payload         jsonb       DEFAULT '{}'::jsonb,
    created_at      timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS prospects (
    id              uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    session_uuid    uuid        NOT NULL
                                REFERENCES sessions(session_uuid) ON DELETE CASCADE,
    customer_id     uuid        REFERENCES customers(id) ON DELETE SET NULL,
    name            text,
    email           text,
    company         text,
    website         text,
    phone           text,
    message         text,
    score           integer     DEFAULT 0,
    consent_given   boolean     DEFAULT false,
    retention_until timestamptz DEFAULT now() + interval '30 days',
    created_at      timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS knowledge_base (
    id              uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    title           text        NOT NULL,
    content         text        NOT NULL,
    category        text        CHECK (category IN ('service', 'faq', 'case_study', 'tech')),
    embedding       vector(1536),
    metadata        jsonb       DEFAULT '{}'::jsonb,
    created_at      timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS voice_calls (
    id               uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    session_uuid     uuid        REFERENCES sessions(session_uuid) ON DELETE SET NULL,
    prospect_id      uuid        REFERENCES prospects(id) ON DELETE SET NULL,
    customer_id      uuid        REFERENCES customers(id) ON DELETE SET NULL,
    provider         text        NOT NULL DEFAULT 'elevenlabs',
    external_call_id text        NOT NULL,
    call_source      text,
    agent_id         text,
    started_at       timestamptz,
    ended_at         timestamptz,
    duration_seconds integer,
    transcript       text,
    summary          text,
    recording_url    text,
    extracted_data   jsonb       DEFAULT '{}'::jsonb,
    metadata         jsonb       DEFAULT '{}'::jsonb,
    raw_payload      jsonb       DEFAULT '{}'::jsonb,
    created_at       timestamptz DEFAULT now(),
    updated_at       timestamptz DEFAULT now(),
    CONSTRAINT voice_calls_provider_external_unique UNIQUE (provider, external_call_id)
);

CREATE INDEX IF NOT EXISTS idx_sessions_session_uuid ON sessions (session_uuid);
CREATE INDEX IF NOT EXISTS idx_interactions_session_uuid ON interactions (session_uuid);
CREATE INDEX IF NOT EXISTS idx_prospects_session_uuid ON prospects (session_uuid);
CREATE INDEX IF NOT EXISTS idx_prospects_customer ON prospects (customer_id);
CREATE INDEX IF NOT EXISTS idx_voice_calls_session ON voice_calls (session_uuid);
CREATE INDEX IF NOT EXISTS idx_knowledge_base_embedding ON knowledge_base
    USING ivfflat (embedding vector_cosine_ops) WITH (lists = 100);

ALTER TABLE knowledge_base ADD CONSTRAINT knowledge_base_title_unique UNIQUE (title);

CREATE OR REPLACE FUNCTION match_knowledge_base(
    query_embedding vector(1536),
    match_threshold float DEFAULT 0.5,
    match_count int DEFAULT 5
)
RETURNS TABLE (
    id uuid, title text, content text, category text, metadata jsonb, similarity float
)
LANGUAGE sql STABLE
AS $$
    SELECT kb.id, kb.title, kb.content, kb.category, kb.metadata,
           1 - (kb.embedding <=> query_embedding) AS similarity
    FROM knowledge_base kb
    WHERE 1 - (kb.embedding <=> query_embedding) > match_threshold
    ORDER BY kb.embedding <=> query_embedding
    LIMIT match_count;
$$;

ALTER TABLE sessions       ENABLE ROW LEVEL SECURITY;
ALTER TABLE interactions   ENABLE ROW LEVEL SECURITY;
ALTER TABLE prospects      ENABLE ROW LEVEL SECURITY;
ALTER TABLE knowledge_base ENABLE ROW LEVEL SECURITY;
ALTER TABLE voice_calls    ENABLE ROW LEVEL SECURITY;

CREATE POLICY "deny_all_anon_sessions" ON sessions FOR ALL TO anon USING (false);
CREATE POLICY "deny_all_anon_interactions" ON interactions FOR ALL TO anon USING (false);
CREATE POLICY "deny_all_anon_prospects" ON prospects FOR ALL TO anon USING (false);
CREATE POLICY "deny_all_anon_knowledge_base" ON knowledge_base FOR ALL TO anon USING (false);
CREATE POLICY "deny_all_anon_voice_calls" ON voice_calls FOR ALL TO anon USING (false);
CREATE POLICY "deny_all_authenticated_sessions" ON sessions FOR ALL TO authenticated USING (false);
CREATE POLICY "deny_all_authenticated_interactions" ON interactions FOR ALL TO authenticated USING (false);
CREATE POLICY "deny_all_authenticated_prospects" ON prospects FOR ALL TO authenticated USING (false);
CREATE POLICY "deny_all_authenticated_knowledge_base" ON knowledge_base FOR ALL TO authenticated USING (false);
CREATE POLICY "deny_all_authenticated_voice_calls" ON voice_calls FOR ALL TO authenticated USING (false);

-- Schema-drift från hemsidans live-DB: source/status/updated_at fanns i drift men inte i repo-migrationen
ALTER TABLE prospects ADD COLUMN IF NOT EXISTS source text;
ALTER TABLE prospects ADD COLUMN IF NOT EXISTS status text DEFAULT 'new';
ALTER TABLE prospects ADD COLUMN IF NOT EXISTS updated_at timestamptz DEFAULT now();
NOTIFY pgrst, 'reload schema';

-- Live-datan har kategorin 'industry' (KUNSKAPSBAS-branscher-v3) som saknades i repo-schemat
ALTER TABLE knowledge_base DROP CONSTRAINT IF EXISTS knowledge_base_category_check;
ALTER TABLE knowledge_base ADD CONSTRAINT knowledge_base_category_check
  CHECK (category IN ('service', 'faq', 'case_study', 'tech', 'industry'));

-- Anonym telemetri från skyland-ai-os.netlify.app.
-- Inga persondata: ingen IP, ingen user-agent, ingen fingerprinting.
create table if not exists public.events (
  id uuid primary key default gen_random_uuid(),
  session_uuid uuid not null,
  type text not null,
  data jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists events_session_idx on public.events (session_uuid, created_at);
create index if not exists events_type_created_idx on public.events (type, created_at desc);
create index if not exists events_created_idx on public.events (created_at desc);

alter table public.events enable row level security;
-- Ingen anon-åtkomst: skrivningar går via n8n (service role), läsning via SCC-backend (service role).

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS pipelines (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    customer_id uuid REFERENCES customers(id) ON DELETE SET NULL,
    name text NOT NULL,
    is_default boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS stages (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    pipeline_id uuid NOT NULL REFERENCES pipelines(id) ON DELETE CASCADE,
    name text NOT NULL,
    position int NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_stages_pipeline ON stages(pipeline_id, position);

CREATE TABLE IF NOT EXISTS opportunities (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    contact_id uuid REFERENCES contacts(id) ON DELETE CASCADE,
    pipeline_id uuid NOT NULL REFERENCES pipelines(id) ON DELETE CASCADE,
    stage_id uuid REFERENCES stages(id) ON DELETE SET NULL,
    customer_id uuid REFERENCES customers(id) ON DELETE SET NULL,
    title text NOT NULL,
    value_sek numeric(12, 2),
    status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'won', 'lost')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_opportunities_pipeline ON opportunities(pipeline_id);
CREATE INDEX IF NOT EXISTS idx_opportunities_stage ON opportunities(stage_id);
CREATE INDEX IF NOT EXISTS idx_opportunities_contact ON opportunities(contact_id);

DO $$
DECLARE
    pid uuid;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pipelines WHERE is_default) THEN
        INSERT INTO pipelines (name, is_default) VALUES ('Sales', true) RETURNING id INTO pid;
        INSERT INTO stages (pipeline_id, name, position) VALUES
            (pid, 'New',       0),
            (pid, 'Contacted', 1),
            (pid, 'Qualified', 2),
            (pid, 'Proposal',  3),
            (pid, 'Won',       4),
            (pid, 'Lost',      5);
    END IF;
END $$;

-- SCC-30 — Outbound messaging: leveransstatus + leverantörs-id på messages.
-- Additiv migration; befintliga rader påverkas inte (status NULL = ej relevant).

ALTER TABLE messages
  ADD COLUMN IF NOT EXISTS status TEXT
    CHECK (status IN ('queued', 'sent', 'failed', 'delivered', 'bounced', 'complained'));

ALTER TABLE messages
  ADD COLUMN IF NOT EXISTS provider_message_id TEXT;

CREATE INDEX IF NOT EXISTS idx_messages_provider_message_id
  ON messages (provider_message_id)
  WHERE provider_message_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_messages_outbound_created
  ON messages (created_at)
  WHERE direction = 'outbound';

-- IG DM är primär outreach-kanal — måste kunna loggas i messages.
alter table messages drop constraint messages_channel_check;
alter table messages add constraint messages_channel_check
  check (channel = any (array['chat'::text, 'voice'::text, 'email'::text, 'sms'::text, 'whatsapp'::text, 'webhook'::text, 'instagram'::text]));

create table if not exists todos (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  notes text,
  done boolean not null default false,
  due_at timestamptz,
  priority text not null default 'normal' check (priority in ('low','normal','high','urgent')),
  contact_id uuid references contacts(id) on delete set null,
  opportunity_id uuid references opportunities(id) on delete set null,
  source text not null default 'manual',
  auto_key text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  completed_at timestamptz
);
create index if not exists idx_todos_done on todos(done);
create index if not exists idx_todos_due on todos(due_at);
create index if not exists idx_todos_contact on todos(contact_id);
-- Bara en öppen auto-todo per nyckel (t.ex. "reply:<contact_id>") — släpps när den bockas av.
create unique index if not exists uq_todos_auto_open on todos(auto_key) where done = false and auto_key is not null;

-- Strukturerad videoanalys per annons (video-watch-skillen skriver, ad-intel läser).
-- Schema för video_analysis (jsonb):
--   hook: {typ, sekunder, beskrivning}
--   klipprytm: text (snabb/medel/lugn + ev. antal klipp)
--   text_on_screen: [{tid, text}]
--   cta: {tidpunkt, typ, text}
--   manniskor, miljo, ljud, helhetsintryck: text
alter table ad_library
  add column if not exists video_analysis jsonb,
  add column if not exists video_analyzed_at timestamptz;

comment on column ad_library.video_analysis is
  'Strukturerad analys av videokreativet (video-watch-skillen). Fast schema: hook{typ,sekunder,beskrivning}, klipprytm, text_on_screen[], cta{tidpunkt,typ,text}, manniskor, miljo, ljud, helhetsintryck.';

-- ============================================================================
-- CE-12 — STATUSMASKIN + append-only audit trail
-- Plus fönsterunderhåll (24h service window / 72h free entry point) som drivs
-- av ce_messages, eftersom faktisk leverans är det enda som får styra klockan.
-- Idempotent.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- ce_lead_events — append-only. UPDATE och DELETE är spärrade i trigger.
-- Detta är faktureringsunderlaget (CE-42) och attributionskedjan.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ce_lead_events (
    id          bigserial PRIMARY KEY,
    tenant_id   uuid NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,
    lead_id     uuid NOT NULL REFERENCES ce_leads(id) ON DELETE CASCADE,
    event_type  text NOT NULL,          -- status_changed | human_takeover | opt_out | erase | note
    from_status text,
    to_status   text,
    actor       text NOT NULL DEFAULT 'system',   -- system | agent | joakim | gustav
    payload     jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_ce_events_lead ON ce_lead_events(lead_id, created_at);
CREATE INDEX IF NOT EXISTS idx_ce_events_tenant_type
    ON ce_lead_events(tenant_id, event_type, created_at DESC);

COMMENT ON TABLE ce_lead_events IS
    'Append-only. Statusövergångar, handoff, opt-out. Underlag för provisionsavstämning.';

CREATE OR REPLACE FUNCTION ce_events_append_only()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'ce_lead_events är append-only (försökte %)', TG_OP;
END;
$$;

DROP TRIGGER IF EXISTS trg_ce_events_no_update ON ce_lead_events;
CREATE TRIGGER trg_ce_events_no_update
    BEFORE UPDATE OR DELETE ON ce_lead_events
    FOR EACH ROW EXECUTE FUNCTION ce_events_append_only();

-- ----------------------------------------------------------------------------
-- Tillåtna statusövergångar.
-- Framåtflödet är strikt; cold/nurture/opted_out nås från vilket läge som helst
-- (verkligheten gör det), och nurture/cold får återupptas till samtal.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION ce_valid_transition(p_from text, p_to text)
RETURNS boolean
LANGUAGE sql IMMUTABLE
AS $$
    SELECT CASE
        WHEN p_from = p_to THEN true
        -- opted_out är slutgiltigt: bara GDPR-radering rör leadet efter det
        WHEN p_from = 'opted_out' THEN false
        -- avfarter tillåtna från alla aktiva lägen
        WHEN p_to IN ('cold', 'nurture', 'opted_out') THEN true
        -- återupptagning
        WHEN p_from IN ('cold', 'nurture') AND p_to IN ('contacted', 'in_conversation', 'qualifying', 'hot') THEN true
        WHEN p_from = 'new'             AND p_to IN ('contacted', 'in_conversation') THEN true
        WHEN p_from = 'contacted'       AND p_to IN ('in_conversation', 'qualifying', 'hot') THEN true
        WHEN p_from = 'in_conversation' AND p_to IN ('qualifying', 'hot', 'handed_off') THEN true
        WHEN p_from = 'qualifying'      AND p_to IN ('in_conversation', 'hot', 'handed_off') THEN true
        WHEN p_from = 'hot'             AND p_to IN ('handed_off', 'booked', 'in_conversation') THEN true
        WHEN p_from = 'handed_off'      AND p_to IN ('booked', 'in_conversation', 'hot') THEN true
        WHEN p_from = 'booked'          AND p_to IN ('paid', 'handed_off') THEN true
        WHEN p_from = 'paid'            AND p_to IN ('booked') THEN true
        ELSE false
    END
$$;

-- ----------------------------------------------------------------------------
-- Statustrigger: validerar övergången, stämplar milstolpar, loggar append-only.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION ce_leads_status_guard()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status NOT IN ('new', 'contacted', 'in_conversation') THEN
            RAISE EXCEPTION 'Nytt lead får inte skapas i status %', NEW.status;
        END IF;
        INSERT INTO ce_lead_events (tenant_id, lead_id, event_type, from_status, to_status, actor, payload)
        VALUES (NEW.tenant_id, NEW.id, 'lead_created', NULL, NEW.status,
                COALESCE(current_setting('app.actor', true), 'system'),
                jsonb_build_object('source', NEW.source, 'channel', NEW.channel,
                                   'ad_id', NEW.ad_id, 'language', NEW.language));
        RETURN NEW;
    END IF;

    IF NEW.status IS DISTINCT FROM OLD.status THEN
        IF NOT ce_valid_transition(OLD.status, NEW.status) THEN
            RAISE EXCEPTION 'Otillåten statusövergång: % -> % (lead %)',
                OLD.status, NEW.status, OLD.id;
        END IF;

        -- Milstolpar stämplas här, aldrig av anroparen
        IF NEW.status IN ('contacted', 'in_conversation') AND NEW.first_contact_at IS NULL THEN
            NEW.first_contact_at := now();
        END IF;
        IF NEW.status = 'hot'        AND NEW.hot_at IS NULL        THEN NEW.hot_at := now();        END IF;
        IF NEW.status = 'handed_off' AND NEW.handed_off_at IS NULL THEN NEW.handed_off_at := now(); END IF;
        IF NEW.status = 'booked'     AND NEW.booked_at IS NULL     THEN NEW.booked_at := now();     END IF;
        IF NEW.status = 'paid'       AND NEW.paid_at IS NULL       THEN NEW.paid_at := now();       END IF;
        IF NEW.status = 'opted_out'  AND NEW.opted_out_at IS NULL  THEN NEW.opted_out_at := now();  END IF;

        INSERT INTO ce_lead_events (tenant_id, lead_id, event_type, from_status, to_status, actor, payload)
        VALUES (NEW.tenant_id, NEW.id, 'status_changed', OLD.status, NEW.status,
                COALESCE(current_setting('app.actor', true), 'system'),
                jsonb_build_object('group_size', NEW.group_size,
                                   'hot_reasons', to_jsonb(NEW.hot_reasons)));
    END IF;

    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_ce_leads_status ON ce_leads;
CREATE TRIGGER trg_ce_leads_status
    BEFORE INSERT OR UPDATE ON ce_leads
    FOR EACH ROW EXECUTE FUNCTION ce_leads_status_guard();

-- ----------------------------------------------------------------------------
-- Human takeover loggas också (CE-41)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION ce_conv_human_guard()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.human_active IS DISTINCT FROM OLD.human_active THEN
        IF NEW.human_active THEN
            NEW.human_active_since := now();
            NEW.next_followup_at := NULL;   -- schemalagda utskick dödas direkt
        ELSE
            NEW.human_active_since := NULL;
        END IF;
        INSERT INTO ce_lead_events (tenant_id, lead_id, event_type, actor, payload)
        VALUES (NEW.tenant_id, NEW.lead_id,
                CASE WHEN NEW.human_active THEN 'human_takeover' ELSE 'human_released' END,
                COALESCE(current_setting('app.actor', true), 'system'),
                jsonb_build_object('conversation_id', NEW.id));
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_ce_conv_human ON ce_conversations;
CREATE TRIGGER trg_ce_conv_human
    BEFORE UPDATE ON ce_conversations
    FOR EACH ROW EXECUTE FUNCTION ce_conv_human_guard();

-- ----------------------------------------------------------------------------
-- FÖNSTERUNDERHÅLL
-- 24h service window: nollställs av varje INKOMMANDE meddelande.
-- 72h free entry point: startar när VÅRT FÖRSTA svar LEVERERAS på en
-- CTWA-konversation. Nollställs aldrig av kundsvar.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION ce_touch_windows()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    v_entry_point text;
    v_free_open   timestamptz;
BEGIN
    IF NEW.direction = 'inbound' THEN
        UPDATE ce_conversations
           SET last_inbound_at = NEW.created_at,
               service_window_expires_at = NEW.created_at + interval '24 hours'
         WHERE id = NEW.conversation_id;
        RETURN NEW;
    END IF;

    -- outbound: räknas först när det faktiskt gått iväg
    IF NEW.status IN ('sent', 'delivered', 'read') THEN
        SELECT entry_point, free_entry_opened_at
          INTO v_entry_point, v_free_open
          FROM ce_conversations WHERE id = NEW.conversation_id;

        UPDATE ce_conversations
           SET last_outbound_at = COALESCE(NEW.delivered_at, NEW.created_at),
               free_entry_opened_at = CASE
                   WHEN v_entry_point = 'ctwa' AND v_free_open IS NULL
                   THEN COALESCE(NEW.delivered_at, NEW.created_at)
                   ELSE free_entry_opened_at END,
               free_entry_expires_at = CASE
                   WHEN v_entry_point = 'ctwa' AND v_free_open IS NULL
                   THEN COALESCE(NEW.delivered_at, NEW.created_at) + interval '72 hours'
                   ELSE free_entry_expires_at END
         WHERE id = NEW.conversation_id;
    END IF;

    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_ce_msg_windows ON ce_messages;
CREATE TRIGGER trg_ce_msg_windows
    AFTER INSERT OR UPDATE OF status ON ce_messages
    FOR EACH ROW EXECUTE FUNCTION ce_touch_windows();

-- ----------------------------------------------------------------------------
-- Utskicksgrind: vad får skickas just nu, och i vilket format?
-- Uppföljningsmotorn (CE-43) och agenten MÅSTE gå via denna.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION ce_send_policy(p_conversation_id uuid)
RETURNS TABLE (
    can_send        boolean,
    reason          text,
    required_format text,     -- 'free_text' | 'template'
    is_free         boolean
)
LANGUAGE plpgsql STABLE
AS $$
DECLARE c record;
BEGIN
    SELECT cv.*, l.status AS lead_status
      INTO c
      FROM ce_conversations cv
      JOIN ce_leads l ON l.id = cv.lead_id
     WHERE cv.id = p_conversation_id;

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, 'conversation_not_found', NULL::text, false; RETURN;
    END IF;
    IF c.lead_status = 'opted_out' THEN
        RETURN QUERY SELECT false, 'opted_out', NULL::text, false; RETURN;
    END IF;
    IF c.human_active THEN
        RETURN QUERY SELECT false, 'human_active', NULL::text, false; RETURN;
    END IF;
    IF c.status <> 'open' THEN
        RETURN QUERY SELECT false, 'conversation_closed', NULL::text, false; RETURN;
    END IF;

    RETURN QUERY SELECT
        true,
        'ok'::text,
        CASE WHEN c.service_window_expires_at > now() THEN 'free_text' ELSE 'template' END,
        COALESCE(c.free_entry_expires_at > now(), false);
END;
$$;

COMMENT ON FUNCTION ce_send_policy(uuid) IS
    'Enda tillåtna vägen till ett utskick. Kollar opt-out, human_active, 24h-fönstret (format) och 72h free entry (kostnad).';

-- ============================================================================
-- CE-10 (del 2) — RLS & TENANT-ISOLERING
-- Skarpt läge: från och med nu ligger extern kunddata (PII) i basen.
--   anon           -> total spärr
--   authenticated  -> ser BARA sin egen tenants rader (claim: tenant_id)
--   service_role   -> bypassar RLS (backenden, bakom Bearer-token)
-- Idempotent.
-- ============================================================================

ALTER TABLE tenants          ENABLE ROW LEVEL SECURITY;
ALTER TABLE ce_leads         ENABLE ROW LEVEL SECURITY;
ALTER TABLE ce_conversations ENABLE ROW LEVEL SECURITY;
ALTER TABLE ce_messages      ENABLE ROW LEVEL SECURITY;
ALTER TABLE ce_customers     ENABLE ROW LEVEL SECURITY;
ALTER TABLE ce_bookings      ENABLE ROW LEVEL SECURITY;
ALTER TABLE ce_payments      ENABLE ROW LEVEL SECURITY;
ALTER TABLE ce_lead_events   ENABLE ROW LEVEL SECURITY;

DO $$
DECLARE t text;
BEGIN
    FOREACH t IN ARRAY ARRAY[
        'ce_leads','ce_conversations','ce_messages','ce_customers',
        'ce_bookings','ce_payments','ce_lead_events'
    ] LOOP
        EXECUTE format('DROP POLICY IF EXISTS deny_all_anon_%1$s ON %1$I', t);
        EXECUTE format('DROP POLICY IF EXISTS tenant_isolation_%1$s ON %1$I', t);

        -- anon får aldrig röra kunddata
        EXECUTE format(
            'CREATE POLICY deny_all_anon_%1$s ON %1$I AS RESTRICTIVE TO anon USING (false)', t);

        -- authenticated ser bara sin egen tenant
        EXECUTE format($p$
            CREATE POLICY tenant_isolation_%1$s ON %1$I
                TO authenticated
                USING (tenant_id = current_tenant_id())
                WITH CHECK (tenant_id = current_tenant_id())
        $p$, t);
    END LOOP;
END;
$$;

-- tenants-tabellen: authenticated ser bara sin egen rad, anon inget
DROP POLICY IF EXISTS deny_all_anon_tenants ON tenants;
DROP POLICY IF EXISTS tenant_self_tenants ON tenants;
CREATE POLICY deny_all_anon_tenants ON tenants AS RESTRICTIVE TO anon USING (false);
CREATE POLICY tenant_self_tenants ON tenants
    FOR SELECT TO authenticated
    USING (id = current_tenant_id());

-- Vyn måste köra med anroparens rättigheter, annars läcker den förbi RLS
