-- Brygga: Cold Experience-händelser syns i SCC:s aktivitetsflöde under Gustavs kundkort.
-- Kopplingen går customers.site_tenant_id -> tenants.id -> ce_*.tenant_id.

create or replace function ce_customer_id(p_tenant uuid)
returns uuid language sql stable as $$
  select c.id from customers c where c.site_tenant_id = p_tenant limit 1;
$$;

-- Idempotens: varje bryggad rad bär sin källhändelses id. Ett unikt index gör
-- backfill och trigger ofarliga att köra om.
create unique index if not exists activities_ce_ref_uidx
  on activities ((details->>'ce_ref')) where details ? 'ce_ref';

create or replace function ce_event_to_activity()
returns trigger language plpgsql as $$
declare
  v_customer uuid;
  v_type text; v_action text; v_sev text; v_auto text;
  v_lead record;
begin
  v_customer := ce_customer_id(new.tenant_id);
  if v_customer is null then return new; end if;

  select name, country, status, channel into v_lead from ce_leads where id = new.lead_id;

  case new.event_type
    when 'form_received'    then v_type:='lead';        v_action:='ce.lead.form_received';  v_sev:='info';  v_auto:='OBSERVE';
    when 'lead_created'     then v_type:='lead';        v_action:='ce.lead.created';        v_sev:='info';  v_auto:='OBSERVE';
    when 'status_changed'   then v_type:='lead';        v_action:='ce.lead.status_changed'; v_sev:='info';  v_auto:='OBSERVE';
    when 'disqualified'     then v_type:='lead';        v_action:='ce.lead.disqualified';   v_sev:='info';  v_auto:='ACT';
    when 'first_email_sent' then v_type:='message';     v_action:='ce.email.sent';          v_sev:='info';  v_auto:='ACT';
    when 'owner_notified'   then v_type:='message';     v_action:='ce.owner.notified';      v_sev:='info';  v_auto:='ACT';
    when 'handoff'          then v_type:='opportunity'; v_action:='ce.lead.handoff';        v_sev:='warn';  v_auto:='ACT';
    when 'human_took_over'  then v_type:='chat';        v_action:='ce.human.took_over';     v_sev:='info';  v_auto:='OBSERVE';
    when 'agent_paused'     then v_type:='system';      v_action:='ce.agent.paused';        v_sev:='warn';  v_auto:='OBSERVE';
    when 'agent_error'      then v_type:='system';      v_action:='ce.agent.error';         v_sev:='error'; v_auto:='OBSERVE';
    else                         v_type:='system';      v_action:='ce.'||new.event_type;    v_sev:='info';  v_auto:='OBSERVE';
  end case;

  insert into activities (customer_id, agent, action, event_type, severity, autonomy_level, details, created_at)
  values (
    v_customer, 'cold-experience', v_action, v_type, v_sev, v_auto,
    jsonb_strip_nulls(jsonb_build_object(
      'ce_ref',   'event:'||new.id::text,
      'lead_id',  new.lead_id,
      'lead',     v_lead.name,
      'country',  v_lead.country,
      'channel',  v_lead.channel,
      'from_status', new.from_status,
      'to_status',   new.to_status,
      'actor',    new.actor,
      'payload',  new.payload
    )),
    new.created_at
  )
  on conflict do nothing;

  return new;
end $$;

create or replace function ce_message_to_activity()
returns trigger language plpgsql as $$
declare
  v_customer uuid;
  v_lead record;
begin
  v_customer := ce_customer_id(new.tenant_id);
  if v_customer is null then return new; end if;

  select name, country into v_lead from ce_leads where id = new.lead_id;

  insert into activities (customer_id, agent, action, event_type, severity, autonomy_level, details, created_at)
  values (
    v_customer, 'cold-experience',
    'ce.message.'||new.direction,
    'message',
    case when new.status = 'failed' then 'error' else 'info' end,
    case when new.direction = 'outbound' then 'ACT' else 'OBSERVE' end,
    jsonb_strip_nulls(jsonb_build_object(
      'ce_ref',  'msg:'||new.id::text,
      'lead_id', new.lead_id,
      'lead',    v_lead.name,
      'country', v_lead.country,
      'channel', new.channel,
      'sender',  new.sender,
      'status',  new.status,
      'preview', left(coalesce(new.body,''), 200),
      'conversation_id', new.conversation_id
    )),
    new.created_at
  )
  on conflict do nothing;

  return new;
end $$;

drop trigger if exists trg_ce_events_to_activities on ce_lead_events;
create trigger trg_ce_events_to_activities
  after insert on ce_lead_events
  for each row execute function ce_event_to_activity();

drop trigger if exists trg_ce_msg_to_activities on ce_messages;
create trigger trg_ce_msg_to_activities
  after insert on ce_messages
  for each row execute function ce_message_to_activity();

comment on function ce_event_to_activity is
  'Speglar ce_lead_events till activities så Cold Experience syns i SCC:s kundvy. details->>ce_ref gör den idempotent.';

-- contacts.dedupe_key har ett PARTIELLT unikt index (where dedupe_key is not null),
-- så ON CONFLICT måste upprepa predikatet för att Postgres ska hitta indexet.
create or replace function ce_mirror_lead(p_lead_id uuid)
returns void language plpgsql as $$
declare
  l record; v_customer uuid; v_pipeline uuid; v_stage uuid; v_contact uuid;
  v_intent text; v_titel text; v_nyckel text;
begin
  select * into l from ce_lead_overview where id = p_lead_id;
  if not found then return; end if;

  select id into v_customer from customers where site_tenant_id = l.tenant_id limit 1;
  select id into v_pipeline from pipelines where name like 'Cold Experience%' limit 1;
  if v_customer is null or v_pipeline is null then return; end if;

  v_intent := coalesce(l.intent, 'unknown');
  v_nyckel := 'ce:' || l.id::text;
  select id into v_stage from stages
    where pipeline_id = v_pipeline and name = ce_stage_for(l.status, v_intent) limit 1;

  insert into contacts (customer_id, tenant_id, name, email, phone, source, status, dedupe_key, tags, custom)
  values (
    v_customer, l.tenant_id,
    coalesce(nullif(l.name,''), 'Okänt namn'), l.email, l.phone,
    'cold_experience', l.status, v_nyckel,
    array_remove(array[
      'cold-experience',
      case when l.country is not null then 'land:'  || lower(l.country) end,
      case when l.channel is not null then 'kanal:' || l.channel end,
      case when l.intent  is not null then 'vill:'  || l.intent end,
      case when not l.answered then 'obesvarad' end
    ], null),
    jsonb_strip_nulls(jsonb_build_object(
      'ce_lead_id', l.id, 'ce_channel', l.channel, 'ce_intent', l.intent,
      'ce_country', l.country, 'ce_message', l.guest_message,
      'ce_last_inbound', l.last_inbound_body, 'ce_received_at', l.received_at,
      'ce_answered', l.answered, 'ce_messages_in', l.messages_in, 'ce_messages_out', l.messages_out,
      'ce_travel_when', l.travel_when, 'ce_days', l.days, 'ce_adults', l.adults,
      'ce_departure', l.departure, 'ce_price_eur', l.price_quoted_eur,
      'ce_callback', l.callback_window, 'ce_ad_name', l.ad_name,
      'ce_form', (select qualification->'form' from ce_leads where id = l.id)
    ))
  )
  on conflict (dedupe_key) where dedupe_key is not null do update set
    name = excluded.name, email = excluded.email, phone = excluded.phone,
    status = excluded.status, tags = excluded.tags, custom = excluded.custom,
    updated_at = now()
  returning id into v_contact;

  if v_contact is null then
    select id into v_contact from contacts where dedupe_key = v_nyckel;
  end if;
  if v_contact is null then return; end if;

  v_titel := coalesce(nullif(l.name,''), 'Okänt namn')
             || case when l.days is not null then ' · ' || l.days || ' dagar' else '' end;

  if exists (select 1 from opportunities where contact_id = v_contact and pipeline_id = v_pipeline) then
    update opportunities set
      stage_id = v_stage, title = v_titel,
      status = case when l.status='booked' then 'won'
                    when l.status in ('cold','lost') then 'lost' else 'open' end,
      updated_at = now()
    where contact_id = v_contact and pipeline_id = v_pipeline;
  else
    insert into opportunities (contact_id, pipeline_id, stage_id, customer_id, tenant_id, title, status)
    values (v_contact, v_pipeline, v_stage, v_customer, l.tenant_id, v_titel,
            case when l.status='booked' then 'won'
                 when l.status in ('cold','lost') then 'lost' else 'open' end);
  end if;
end $$;

-- Håll speglingen färsk.

create or replace function ce_leads_mirror_trg()
returns trigger language plpgsql as $$
begin
  perform ce_mirror_lead(new.id);
  return new;
end $$;

drop trigger if exists trg_ce_leads_mirror on ce_leads;
create trigger trg_ce_leads_mirror
  after insert or update on ce_leads
  for each row execute function ce_leads_mirror_trg();

-- Ett nytt meddelande ändrar "obesvarad" och antalen på kortet.
create or replace function ce_msg_mirror_trg()
returns trigger language plpgsql as $$
begin
  if new.lead_id is not null then perform ce_mirror_lead(new.lead_id); end if;
  return new;
end $$;

drop trigger if exists trg_ce_msg_mirror on ce_messages;
create trigger trg_ce_msg_mirror
  after insert on ce_messages
