    coalesce(nullif(l.name,''), 'Okänt namn'), l.email, l.phone,
    'cold_experience', ce_contact_status_for(l.status), v_nyckel,
    array_remove(array[
      'cold-experience',
      case when l.country is not null then 'land:'  || lower(l.country) end,
      case when l.channel is not null then 'kanal:' || l.channel end,
      case when l.intent  is not null then 'vill:'  || l.intent end,
      case when not l.answered then 'obesvarad' end
    ], null),
    jsonb_strip_nulls(jsonb_build_object(
      'ce_lead_id', l.id, 'ce_channel', l.channel, 'ce_intent', l.intent,
      'ce_country', l.country, 'ce_message', l.guest_message,
      'ce_last_inbound', l.last_inbound_body, 'ce_received_at', l.received_at,
      'ce_answered', l.answered, 'ce_messages_in', l.messages_in, 'ce_messages_out', l.messages_out,
      'ce_travel_when', l.travel_when, 'ce_days', l.days, 'ce_adults', l.adults,
      'ce_departure', l.departure, 'ce_price_eur', l.price_quoted_eur,
      'ce_callback', l.callback_window, 'ce_ad_name', l.ad_name, 'ce_status', l.status,
      'ce_form', (select qualification->'form' from ce_leads where id = l.id)
    ))
  )
  on conflict (dedupe_key) where dedupe_key is not null do update set
    name = excluded.name, email = excluded.email, phone = excluded.phone,
    status = excluded.status, tags = excluded.tags, custom = excluded.custom,
    updated_at = now()
  returning id into v_contact;

  if v_contact is null then select id into v_contact from contacts where dedupe_key = v_nyckel; end if;
  if v_contact is null then return; end if;

  v_titel := coalesce(nullif(l.name,''), 'Okänt namn')
             || case when l.days is not null then ' · ' || l.days || ' dagar' else '' end;

  if exists (select 1 from opportunities where contact_id = v_contact and pipeline_id = v_pipeline) then
    update opportunities set stage_id = v_stage, title = v_titel,
      status = case when l.status='booked' then 'won'
                    when l.status in ('cold','lost','opted_out') then 'lost' else 'open' end,
      updated_at = now()
    where contact_id = v_contact and pipeline_id = v_pipeline;
  else
    insert into opportunities (contact_id, pipeline_id, stage_id, customer_id, tenant_id, title, status)
    values (v_contact, v_pipeline, v_stage, v_customer, l.tenant_id, v_titel,
            case when l.status='booked' then 'won'
                 when l.status in ('cold','lost','opted_out') then 'lost' else 'open' end);
  end if;
end $$;

-- Skrivning tillbaka, nu som BEFORE UPDATE så en otillåten flytt kan nekas snyggt
-- i stället för att kasta ett fel mitt i dra-och-släpp.
drop trigger if exists trg_ce_opp_writeback on opportunities;

create or replace function ce_opp_stage_writeback()
returns trigger language plpgsql as $$
declare v_lead uuid; v_steg text; v_ny text; v_nu text;
begin
  select (c.custom->>'ce_lead_id')::uuid into v_lead
    from contacts c where c.id = new.contact_id and c.dedupe_key like 'ce:%';
  if v_lead is null then return new; end if;

  select name into v_steg from stages where id = new.stage_id;
  if v_steg is null then return new; end if;

  v_ny := ce_status_for(v_steg);
  select status into v_nu from ce_leads where id = v_lead;

  if v_nu is not distinct from v_ny then return new; end if;

  -- Respektera systemets egen övergångsgraf. Är flytten otillåten snäpper
  -- kortet tillbaka i stället för att spränga uppdateringen.
  if not ce_valid_transition(v_nu, v_ny) then
    raise warning 'CE: otillåten flytt % -> % (lead %), kortet snappar tillbaka', v_nu, v_ny, v_lead;
    new.stage_id := old.stage_id;
    return new;
  end if;

  update ce_leads set status = v_ny, updated_at = now() where id = v_lead;
  insert into ce_lead_events (tenant_id, lead_id, event_type, from_status, to_status, actor, payload)
  select tenant_id, v_lead, 'status_changed', v_nu, v_ny, 'human',
         jsonb_build_object('via','crm-kanban','steg',v_steg)
  from ce_leads where id = v_lead;
  return new;
end $$;

create trigger trg_ce_opp_writeback
  before update of stage_id on opportunities
  for each row when (old.stage_id is distinct from new.stage_id)
  execute function ce_opp_stage_writeback();

-- Speglingen uppdaterar opportunities, vilket väckte tillbakaskrivningen, som
-- uppdaterade ce_leads, som väckte speglingen igen. Postgres stoppade det med
-- "tuple already modified". Flaggan gör riktningen entydig: när vi speglar
-- NEDÅT (ce_leads -> CRM) ska tillbakaskrivningen hålla tyst.

create or replace function ce_mirroring()
returns boolean language sql stable as $$
  select coalesce(current_setting('ce.mirroring', true), '0') = '1';
$$;

create or replace function ce_opp_stage_writeback()
returns trigger language plpgsql as $$
declare v_lead uuid; v_steg text; v_ny text; v_nu text;
begin
  -- Flytten kommer från speglingen själv, inte från en människa som drog ett kort.
  if ce_mirroring() then return new; end if;

  select (c.custom->>'ce_lead_id')::uuid into v_lead
    from contacts c where c.id = new.contact_id and c.dedupe_key like 'ce:%';
  if v_lead is null then return new; end if;

  select name into v_steg from stages where id = new.stage_id;
  if v_steg is null then return new; end if;

  v_ny := ce_status_for(v_steg);
  select status into v_nu from ce_leads where id = v_lead;
  if v_nu is not distinct from v_ny then return new; end if;

  if not ce_valid_transition(v_nu, v_ny) then
    raise warning 'CE: otillåten flytt % -> % (lead %), kortet snappar tillbaka', v_nu, v_ny, v_lead;
    new.stage_id := old.stage_id;
    return new;
  end if;

  update ce_leads set status = v_ny, updated_at = now() where id = v_lead;
  insert into ce_lead_events (tenant_id, lead_id, event_type, from_status, to_status, actor, payload)
  select tenant_id, v_lead, 'status_changed', v_nu, v_ny, 'human',
         jsonb_build_object('via','crm-kanban','steg',v_steg)
  from ce_leads where id = v_lead;
  return new;
end $$;

create or replace function ce_mirror_lead(p_lead_id uuid)
returns void language plpgsql as $$
declare
  l record; v_customer uuid; v_pipeline uuid; v_stage uuid; v_contact uuid;
  v_titel text; v_nyckel text; v_hot boolean; v_forra text;
begin
  select * into l from ce_lead_overview where id = p_lead_id;
  if not found then return; end if;

  select id into v_customer from customers where site_tenant_id = l.tenant_id limit 1;
  select id into v_pipeline from pipelines where name like 'Cold Experience%' limit 1;
  if v_customer is null or v_pipeline is null then return; end if;

  v_forra := coalesce(current_setting('ce.mirroring', true), '0');
  perform set_config('ce.mirroring', '1', true);

  v_hot := l.hot_at is not null;
  v_nyckel := 'ce:' || l.id::text;
  select s.id into v_stage from stages s
    where s.pipeline_id = v_pipeline and s.name = ce_stage_for(l.status, v_hot) limit 1;

  insert into contacts (customer_id, tenant_id, name, email, phone, source, status, dedupe_key, tags, custom)
  values (
    v_customer, l.tenant_id,
    coalesce(nullif(l.name,''), 'Okänt namn'), l.email, l.phone,
    'cold_experience', ce_contact_status_for(l.status), v_nyckel,
    array_remove(array[
      'cold-experience',
      case when l.country is not null then 'land:'  || lower(l.country) end,
      case when l.channel is not null then 'kanal:' || l.channel end,
      case when l.intent  is not null then 'vill:'  || l.intent end,
      case when not l.answered then 'obesvarad' end
    ], null),
    jsonb_strip_nulls(jsonb_build_object(
      'ce_lead_id', l.id, 'ce_channel', l.channel, 'ce_intent', l.intent,
      'ce_country', l.country, 'ce_message', l.guest_message,
      'ce_last_inbound', l.last_inbound_body, 'ce_received_at', l.received_at,
      'ce_answered', l.answered, 'ce_messages_in', l.messages_in, 'ce_messages_out', l.messages_out,
      'ce_travel_when', l.travel_when, 'ce_days', l.days, 'ce_adults', l.adults,
      'ce_departure', l.departure, 'ce_price_eur', l.price_quoted_eur,
      'ce_callback', l.callback_window, 'ce_ad_name', l.ad_name, 'ce_status', l.status,
      'ce_form', (select qualification->'form' from ce_leads where id = l.id)
    ))
  )
  on conflict (dedupe_key) where dedupe_key is not null do update set
    name = excluded.name, email = excluded.email, phone = excluded.phone,
    status = excluded.status, tags = excluded.tags, custom = excluded.custom,
    updated_at = now()
  returning id into v_contact;

  if v_contact is null then select id into v_contact from contacts where dedupe_key = v_nyckel; end if;

  if v_contact is not null then
    v_titel := coalesce(nullif(l.name,''), 'Okänt namn')
               || case when l.days is not null then ' · ' || l.days || ' dagar' else '' end;

    if exists (select 1 from opportunities where contact_id = v_contact and pipeline_id = v_pipeline) then
      update opportunities set stage_id = v_stage, title = v_titel,
        status = case when l.status='booked' then 'won'
                      when l.status in ('cold','lost','opted_out') then 'lost' else 'open' end,
        updated_at = now()
      where contact_id = v_contact and pipeline_id = v_pipeline
        and (stage_id is distinct from v_stage or title is distinct from v_titel);
    else
      insert into opportunities (contact_id, pipeline_id, stage_id, customer_id, tenant_id, title, status)
      values (v_contact, v_pipeline, v_stage, v_customer, l.tenant_id, v_titel,
              case when l.status='booked' then 'won'
                   when l.status in ('cold','lost','opted_out') then 'lost' else 'open' end);
    end if;
  end if;

  perform set_config('ce.mirroring', v_forra, true);
end $$;

-- Korten i Het har status 'new' (formulärleads stämplas hot_at men får inte gå
-- new -> hot). Drar Gustav ett sådant kort till Överlämnad är den direkta
-- övergången otillåten, trots att vägen new -> in_conversation -> handed_off är det.
-- I stället för att neka flytten går vi via mellansteget. Varje enskild övergång
-- valideras fortfarande av systemets egen ce_valid_transition.

create or replace function ce_opp_stage_writeback()
returns trigger language plpgsql as $$
declare
  v_lead uuid; v_steg text; v_mal text; v_nu text; v_via text;
  KANDIDATER text[] := array['contacted','in_conversation','qualifying','hot','handed_off'];
begin
  if ce_mirroring() then return new; end if;

  select (c.custom->>'ce_lead_id')::uuid into v_lead
    from contacts c where c.id = new.contact_id and c.dedupe_key like 'ce:%';
  if v_lead is null then return new; end if;

  select name into v_steg from stages where id = new.stage_id;
  if v_steg is null then return new; end if;

  v_mal := ce_status_for(v_steg);
  select status into v_nu from ce_leads where id = v_lead;
  if v_nu is not distinct from v_mal then return new; end if;

  if ce_valid_transition(v_nu, v_mal) then
    update ce_leads set status = v_mal, updated_at = now() where id = v_lead;
    insert into ce_lead_events (tenant_id, lead_id, event_type, from_status, to_status, actor, payload)
    select tenant_id, v_lead, 'status_changed', v_nu, v_mal, 'human',
           jsonb_build_object('via','crm-kanban','steg',v_steg)
    from ce_leads where id = v_lead;
    return new;
  end if;

  -- Ett hopp räcker nästan alltid: hitta ett mellanläge som är lagligt åt båda hållen.
  select k into v_via from unnest(KANDIDATER) k
   where k <> v_nu and k <> v_mal
     and ce_valid_transition(v_nu, k) and ce_valid_transition(k, v_mal)
   limit 1;

  if v_via is null then
    raise warning 'CE: ingen laglig väg % -> % (lead %), kortet snappar tillbaka', v_nu, v_mal, v_lead;
    new.stage_id := old.stage_id;
    return new;
  end if;

  update ce_leads set status = v_via, updated_at = now() where id = v_lead;
  insert into ce_lead_events (tenant_id, lead_id, event_type, from_status, to_status, actor, payload)
  select tenant_id, v_lead, 'status_changed', v_nu, v_via, 'human',
         jsonb_build_object('via','crm-kanban','steg',v_steg,'mellansteg',true)
  from ce_leads where id = v_lead;

  update ce_leads set status = v_mal, updated_at = now() where id = v_lead;
  insert into ce_lead_events (tenant_id, lead_id, event_type, from_status, to_status, actor, payload)
  select tenant_id, v_lead, 'status_changed', v_via, v_mal, 'human',
         jsonb_build_object('via','crm-kanban','steg',v_steg)
  from ce_leads where id = v_lead;

  return new;
end $$;

-- Flaggan skyddade bara ena riktningen. Tillbakaskrivningen uppdaterade ce_leads,
-- vilket väckte speglingen, som ville röra samma opportunities-rad som just då
-- uppdaterades i en BEFORE-trigger. Nu tystar flaggan speglingen åt båda håll,
-- och kortets nya läge sätts ändå av new.stage_id som användaren valde.

create or replace function ce_leads_mirror_trg()
returns trigger language plpgsql as $$
begin
  if ce_mirroring() then return new; end if;
  perform ce_mirror_lead(new.id);
  return new;
end $$;

create or replace function ce_opp_stage_writeback()
returns trigger language plpgsql as $$
declare
  v_lead uuid; v_steg text; v_mal text; v_nu text; v_via text; v_forra text;
  KANDIDATER text[] := array['contacted','in_conversation','qualifying','hot','handed_off'];
begin
  if ce_mirroring() then return new; end if;

  select (c.custom->>'ce_lead_id')::uuid into v_lead
    from contacts c where c.id = new.contact_id and c.dedupe_key like 'ce:%';
  if v_lead is null then return new; end if;

  select name into v_steg from stages where id = new.stage_id;
  if v_steg is null then return new; end if;

  v_mal := ce_status_for(v_steg);
  select status into v_nu from ce_leads where id = v_lead;
  if v_nu is not distinct from v_mal then return new; end if;

  if not ce_valid_transition(v_nu, v_mal) then
    select k into v_via from unnest(KANDIDATER) k
     where k <> v_nu and k <> v_mal
       and ce_valid_transition(v_nu, k) and ce_valid_transition(k, v_mal)
     limit 1;
    if v_via is null then
      raise warning 'CE: ingen laglig väg % -> % (lead %), kortet snappar tillbaka', v_nu, v_mal, v_lead;
      new.stage_id := old.stage_id;
      return new;
    end if;
  end if;

  -- Tysta speglingen medan vi skriver, annars vill den röra kortet vi står i.
  v_forra := coalesce(current_setting('ce.mirroring', true), '0');
  perform set_config('ce.mirroring', '1', true);

  if v_via is not null then
    update ce_leads set status = v_via, updated_at = now() where id = v_lead;
    insert into ce_lead_events (tenant_id, lead_id, event_type, from_status, to_status, actor, payload)
    select tenant_id, v_lead, 'status_changed', v_nu, v_via, 'human',
           jsonb_build_object('via','crm-kanban','steg',v_steg,'mellansteg',true)
    from ce_leads where id = v_lead;
    v_nu := v_via;
  end if;

  update ce_leads set status = v_mal, updated_at = now() where id = v_lead;
  insert into ce_lead_events (tenant_id, lead_id, event_type, from_status, to_status, actor, payload)
  select tenant_id, v_lead, 'status_changed', v_nu, v_mal, 'human',
         jsonb_build_object('via','crm-kanban','steg',v_steg)
  from ce_leads where id = v_lead;

  perform set_config('ce.mirroring', v_forra, true);

  -- Håll kontaktens statusfält i takt utan att gå via speglingen.
  update contacts set status = ce_contact_status_for(v_mal),
                      custom = jsonb_set(coalesce(custom,'{}'::jsonb), '{ce_status}', to_jsonb(v_mal)),
                      updated_at = now()
  where id = new.contact_id;

  return new;
end $$;

-- Speglar ce_messages till messages så den befintliga ConversationInbox visar
-- tråden. Kopplingen till kontakten går via metadata->>'contact_id', samma väg
-- som de befintliga meddelandena använder.

create unique index if not exists messages_ce_ref_uidx
  on messages ((metadata->>'ce_message_id')) where metadata ? 'ce_message_id';

create or replace function ce_mirror_message(p_msg_id uuid)
returns void language plpgsql as $$
declare m record; v_contact uuid; v_customer uuid;
begin
  select * into m from ce_messages where id = p_msg_id;
  if not found or m.lead_id is null then return; end if;

  select c.id, c.customer_id into v_contact, v_customer
    from contacts c where c.dedupe_key = 'ce:' || m.lead_id::text;
  if v_contact is null then return; end if;

  insert into messages (customer_id, conversation_id, role, channel, direction,
                        content, status, provider_message_id, metadata, created_at)
  values (
    v_customer, m.conversation_id,
    case when m.direction = 'inbound' then 'user' else 'assistant' end,
    m.channel, m.direction,
    coalesce(m.body, ''), m.status, m.external_id,
    jsonb_build_object(
      'contact_id',    v_contact,
      'ce_message_id', m.id,
      'ce_lead_id',    m.lead_id,
      'sender',        m.sender
    ),
    m.created_at
  )
  on conflict ((metadata->>'ce_message_id')) where metadata ? 'ce_message_id'
  do update set content = excluded.content, status = excluded.status, metadata = excluded.metadata;
end $$;

create or replace function ce_msg_mirror_trg()
returns trigger language plpgsql as $$
begin
  if new.lead_id is not null then
    perform ce_mirror_lead(new.lead_id);   -- kortet: obesvarad, antal
    perform ce_mirror_message(new.id);     -- tråden
  end if;
  return new;
end $$;

comment on function ce_mirror_message is
  'Projicerar ett ce_messages-rad till messages så ConversationInbox hittar den. Idempotent på metadata->>ce_message_id.';

-- messages.channel tillät chat, voice, email, sms, whatsapp, webhook, instagram.
-- Messenger saknades trots att instagram, dess syskonkanal hos Meta, redan fanns.
-- Additiv ändring: inga befintliga rader påverkas.
alter table messages drop constraint messages_channel_check;
alter table messages add constraint messages_channel_check
  check (channel = any (array['chat','voice','email','sms','whatsapp','messenger','webhook','instagram']));

-- ce_mirror_lead skrev "custom = excluded.custom", alltså HELA objektet.
-- Spegeln äger bara ce_*-nycklarna; dm_hook (mejlutkasten) och ce_subject bor på
-- samma ställe men skrivs av annat. Ett enda inkommande meddelande hade därför
-- raderat gästens eget utkast mitt i sekvensen, tyst.
--
-- Nu slås objekten ihop med högersidan vinnande: spegelns nycklar uppdateras,
-- allt annat på kortet överlever. Priset är att ett fält som TÖMS på leaden
-- ligger kvar med sitt gamla värde, eftersom jsonb_strip_nulls tar bort nyckeln
-- i stället för att sätta den till null. Det är rätt håll att fela åt: ett
-- inaktuellt fält syns och kan rättas, ett raderat utkast är borta.
create or replace function public.ce_mirror_lead(p_lead_id uuid)
 returns void
 language plpgsql
as $function$
declare
  l record; v_customer uuid; v_pipeline uuid; v_stage uuid; v_contact uuid;
  v_titel text; v_nyckel text; v_hot boolean; v_forra text;
begin
  select * into l from ce_lead_overview where id = p_lead_id;
  if not found then return; end if;

  select id into v_customer from customers where site_tenant_id = l.tenant_id limit 1;
  select id into v_pipeline from pipelines where name like 'Cold Experience%' limit 1;
  if v_customer is null or v_pipeline is null then return; end if;

  v_forra := coalesce(current_setting('ce.mirroring', true), '0');
  perform set_config('ce.mirroring', '1', true);

  v_hot := l.hot_at is not null;
  v_nyckel := 'ce:' || l.id::text;
  select s.id into v_stage from stages s
    where s.pipeline_id = v_pipeline and s.name = ce_stage_for(l.status, v_hot) limit 1;

  insert into contacts (customer_id, tenant_id, name, email, phone, source, status, dedupe_key, tags, custom)
  values (
    v_customer, l.tenant_id,
    coalesce(nullif(l.name,''), 'Okänt namn'), l.email, l.phone,
    'cold_experience', ce_contact_status_for(l.status), v_nyckel,
    array_remove(array[
      'cold-experience',
      case when l.country is not null then 'land:'  || lower(l.country) end,
      case when l.channel is not null then 'kanal:' || l.channel end,
      case when l.intent  is not null then 'vill:'  || l.intent end,
      case when not l.answered then 'obesvarad' end
    ], null),
    jsonb_strip_nulls(jsonb_build_object(
      'ce_lead_id', l.id, 'ce_channel', l.channel, 'ce_intent', l.intent,
      'ce_country', l.country, 'ce_message', l.guest_message,
      'ce_last_inbound', l.last_inbound_body, 'ce_received_at', l.received_at,
      'ce_answered', l.answered, 'ce_messages_in', l.messages_in, 'ce_messages_out', l.messages_out,
      'ce_travel_when', l.travel_when, 'ce_days', l.days, 'ce_adults', l.adults,
      'ce_departure', l.departure, 'ce_price_eur', l.price_quoted_eur,
      'ce_callback', l.callback_window, 'ce_ad_name', l.ad_name, 'ce_status', l.status,
      'ce_form', (select qualification->'form' from ce_leads where id = l.id)
    ))
  )
  on conflict (dedupe_key) where dedupe_key is not null do update set
    name = excluded.name, email = excluded.email, phone = excluded.phone,
    status = excluded.status, tags = excluded.tags,
    custom = coalesce(contacts.custom, '{}'::jsonb) || excluded.custom,
    updated_at = now()
  returning id into v_contact;

  if v_contact is null then select id into v_contact from contacts where dedupe_key = v_nyckel; end if;

  if v_contact is not null then
    v_titel := coalesce(nullif(l.name,''), 'Okänt namn')
               || case when l.days is not null then ' · ' || l.days || ' dagar' else '' end;

    if exists (select 1 from opportunities where contact_id = v_contact and pipeline_id = v_pipeline) then
      update opportunities set stage_id = v_stage, title = v_titel,
        status = case when l.status='booked' then 'won'
                      when l.status in ('cold','lost','opted_out') then 'lost' else 'open' end,
        updated_at = now()
      where contact_id = v_contact and pipeline_id = v_pipeline
        and (stage_id is distinct from v_stage or title is distinct from v_titel);
    else
      insert into opportunities (contact_id, pipeline_id, stage_id, customer_id, tenant_id, title, status)
      values (v_contact, v_pipeline, v_stage, v_customer, l.tenant_id, v_titel,
              case when l.status='booked' then 'won'
                   when l.status in ('cold','lost','opted_out') then 'lost' else 'open' end);
    end if;
  end if;

  perform set_config('ce.mirroring', v_forra, true);
end $function$;

-- ce_jobs hade ingen klocka: kön kördes bara vid GET ?run_jobs=1 eller efter nästa inkommande
-- webhook, så ett utskick i lugn period låg tills nästa gäst hörde av sig. Nu tickar pg_cron var
-- femte minut och anropar båda funktionerna. Anropen är idempotenta (claim på status=pending).
-- 8 sep 2026.

create extension if not exists pg_cron with schema pg_catalog;
create extension if not exists pg_net with schema extensions;

select cron.unschedule(jobname) from cron.job where jobname in ('ce_agent_run_jobs','ce_leads_run_jobs');

select cron.schedule(
  'ce_agent_run_jobs',
  '*/5 * * * *',
  $$ select net.http_get(
       url := 'https://wfwqjxsuvbacvcmpiesl.supabase.co/functions/v1/ce-agent-webhook?run_jobs=1',
       headers := '{"Content-Type":"application/json"}'::jsonb,
       timeout_milliseconds := 20000
     ); $$
);

select cron.schedule(
  'ce_leads_run_jobs',
  '2-59/5 * * * *',
  $$ select net.http_get(
       url := 'https://wfwqjxsuvbacvcmpiesl.supabase.co/functions/v1/meta-leads-webhook?run_jobs=1',
       headers := '{"Content-Type":"application/json"}'::jsonb,
       timeout_milliseconds := 20000
     ); $$
);

-- Kontohändelser från Meta/Dualhook som inte hör till ett lead: ACCOUNT_OFFBOARDED,
-- PARTNER_REMOVED, kvalitetsändringar på numret, okända payloads. Append-only,
-- bara service role läser och skriver (RLS på, inga policies, samma som ce_jobs).
create table if not exists public.ce_account_events (
  id          bigint generated always as identity primary key,
  tenant_id   uuid not null,
  source      text not null default 'whatsapp',   -- whatsapp | unknown_object
  field       text,                                -- account_update, phone_number_quality_update ...
  event       text not null,                       -- ACCOUNT_OFFBOARDED, PARTNER_REMOVED, unknown ...
  severity    text not null default 'info' check (severity in ('info','warn','alarm')),
  waba_id     text,
  phone       text,
  notified    jsonb not null default '{}'::jsonb,  -- {email: id|error, sms: id|error}
  payload     jsonb not null default '{}'::jsonb,
  created_at  timestamptz not null default now()
);
create index if not exists ce_account_events_created_idx on public.ce_account_events (tenant_id, created_at desc);
alter table public.ce_account_events enable row level security;

create or replace function public.ce_account_events_append_only() returns trigger
language plpgsql as $$
begin
  if tg_op = 'DELETE' and coalesce(current_setting('app.allow_event_purge', true), 'false') = 'true' then
    return old;
  end if;
  raise exception 'ce_account_events är append-only (försökte %). Hård radering kräver app.allow_event_purge.', tg_op;
end $$;

drop trigger if exists trg_ce_account_events_append_only on public.ce_account_events;
create trigger trg_ce_account_events_append_only
  before update or delete on public.ce_account_events
  for each row execute function public.ce_account_events_append_only();

-- Daglig hämtning av egna annonssiffror.
--
-- Fönstret är tre dagar bakåt, inte bara gårdagen: Meta räknar om resultat i
-- efterhand när attributionsfönstret stänger, så gårdagens siffra är inte
-- slutgiltig. upsert på (platform, ad_id, date) gör omhämtningen gratis.
--
-- Nyckeln ligger i vault, inte i jobbet. Saknas den gör funktionen ingenting
-- och loggar det, i stället för att skicka ett anrop som ändå nekas.

create or replace function ads_sync_daglig()
returns void
language plpgsql
security definer
set search_path = public, vault, pg_temp
as $$
declare
    nyckel text;
    fran   date := current_date - 3;
    till   date := current_date - 1;
begin
    select decrypted_secret into nyckel
      from vault.decrypted_secrets where name = 'ADS_SYNC_KEY' limit 1;

    if nyckel is null then
        raise notice 'ads_sync: ADS_SYNC_KEY saknas i vault, hoppar över';
        return;
    end if;

    perform net.http_post(
        url := 'https://wfwqjxsuvbacvcmpiesl.supabase.co/functions/v1/ads-sync'
               || '?from=' || fran::text || '&to=' || till::text,
        headers := jsonb_build_object('Content-Type', 'application/json', 'x-ads-key', nyckel),
        body := '{}'::jsonb,
        timeout_milliseconds := 120000
    );
end $$;

comment on function ads_sync_daglig is
'Anropar ads-sync för de tre senaste dagarna. Läser ADS_SYNC_KEY ur vault; utan den gör den ingenting.';

select cron.schedule('ads_sync_daglig', '15 6 * * *', 'select ads_sync_daglig();');

ALTER TABLE public.sessions ADD COLUMN IF NOT EXISTS is_robot boolean NOT NULL DEFAULT false;

CREATE OR REPLACE FUNCTION public.ar_robot(ua text) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT ua IS NOT NULL AND btrim(ua) <> '' AND (
         btrim(ua) !~* '^mozilla/'
      OR ua ~* ('(?<!cu)bot\y|bot/|crawl|spider|slurp|scrap|headless|lighthouse|pagespeed|gtmetrix|pingdom|uptime|statuscake|site24x7'
             || '|moto g power \(2022\)|edge/12\.246'
             || '|bingpreview|facebookexternalhit|meta-external|meta-webindexer'
             || '|google-inspectiontool|googleother|google-read-aloud|adsbot|mediapartners'
             || '|dataprovider|bitsight|ahrefs|semrush|mj12|petalbot|yandex|baidu|sogou'
             || '|bytespider|gptbot|claudebot|perplexity|ccbot|applebot|duckduck'
             || '|linkedinbot|twitterbot|slackbot|discordbot|telegrambot|whatsapp'
             || '|curl/|wget|python|axios|node-fetch|undici|go-http|java/|okhttp|httpclient|postman'))
$$;

UPDATE public.sessions s SET is_robot = true
WHERE NOT s.is_robot
  AND public.ar_robot(s.user_agent)
  AND NOT EXISTS (SELECT 1 FROM public.prospects p WHERE p.session_uuid = s.session_uuid)
  AND NOT EXISTS (SELECT 1 FROM public.voice_calls v WHERE v.session_uuid = s.session_uuid)
  AND NOT EXISTS (SELECT 1 FROM public.interactions i WHERE i.session_uuid = s.session_uuid);

CREATE INDEX IF NOT EXISTS idx_sessions_is_robot ON public.sessions (tenant_id) WHERE is_robot;

CREATE TABLE IF NOT EXISTS public.events_robot_arkiv (LIKE public.events INCLUDING ALL);
ALTER TABLE public.events_robot_arkiv ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'events_robot_arkiv' AND policyname = 'anon_spärr') THEN
    CREATE POLICY anon_spärr ON public.events_robot_arkiv AS RESTRICTIVE FOR ALL TO anon, authenticated USING (false);
  END IF;
END $$;

WITH flyttade AS (
  DELETE FROM public.events e
  USING public.sessions s
  WHERE s.session_uuid = e.session_uuid AND s.is_robot
  RETURNING e.*
)
INSERT INTO public.events_robot_arkiv SELECT * FROM flyttade ON CONFLICT DO NOTHING;

-- Speglingen skapade och uppdaterade, men städade aldrig.
--
-- ce_mirror_lead läser ce_lead_overview, som filtrerar bort erased_at. När ett lead
-- doldes hittade funktionen ingenting och returnerade tyst, medan kontakten och
-- affären låg kvar i CRM-brädet för alltid. Det märktes 17 sep när fyra testkort
-- för Gustav, Julia och Joakim vägrade försvinna, plus två föräldralösa kort vars
-- ce_leads-rad var helt borta sedan tidigare.
--
-- Nu: hittas inte leadet i vyn, ta bort speglingen i stället för att lämna den.

create or replace function public.ce_mirror_lead(p_lead_id uuid)
 returns void
 language plpgsql
as $function$
declare
  l record; v_customer uuid; v_pipeline uuid; v_stage uuid; v_contact uuid;
  v_titel text; v_nyckel text; v_hot boolean; v_forra text;
begin
  v_nyckel := 'ce:' || p_lead_id::text;

  select * into l from ce_lead_overview where id = p_lead_id;
  if not found then
    -- Leadet är dolt eller borta. Riv kopian, annars spökar den kvar i brädet.
    v_forra := coalesce(current_setting('ce.mirroring', true), '0');
    perform set_config('ce.mirroring', '1', true);
    delete from opportunities o
     using contacts c
     where o.contact_id = c.id and c.dedupe_key = v_nyckel;
    delete from contacts where dedupe_key = v_nyckel;
    perform set_config('ce.mirroring', v_forra, true);
    return;
  end if;

  select id into v_customer from customers where site_tenant_id = l.tenant_id limit 1;
  select id into v_pipeline from pipelines where name like 'Cold Experience%' limit 1;
  if v_customer is null or v_pipeline is null then return; end if;

  v_forra := coalesce(current_setting('ce.mirroring', true), '0');
  perform set_config('ce.mirroring', '1', true);

  v_hot := l.hot_at is not null;
  select s.id into v_stage from stages s
    where s.pipeline_id = v_pipeline and s.name = ce_stage_for(l.status, v_hot) limit 1;

  insert into contacts (customer_id, tenant_id, name, email, phone, source, status, dedupe_key, tags, custom)
  values (
    v_customer, l.tenant_id,
    coalesce(nullif(l.name,''), 'Okänt namn'), l.email, l.phone,
    'cold_experience', ce_contact_status_for(l.status), v_nyckel,
    array_remove(array[
      'cold-experience',
      case when l.country is not null then 'land:'  || lower(l.country) end,
      case when l.channel is not null then 'kanal:' || l.channel end,
      case when l.intent  is not null then 'vill:'  || l.intent end,
      case when not l.answered then 'obesvarad' end
    ], null),
    jsonb_strip_nulls(jsonb_build_object(
      'ce_lead_id', l.id, 'ce_channel', l.channel, 'ce_intent', l.intent,
      'ce_country', l.country, 'ce_message', l.guest_message,
      'ce_last_inbound', l.last_inbound_body, 'ce_received_at', l.received_at,
      'ce_answered', l.answered, 'ce_messages_in', l.messages_in, 'ce_messages_out', l.messages_out,
      'ce_travel_when', l.travel_when, 'ce_days', l.days, 'ce_adults', l.adults,
      'ce_departure', l.departure, 'ce_price_eur', l.price_quoted_eur,
      'ce_callback', l.callback_window, 'ce_ad_name', l.ad_name, 'ce_status', l.status,
      -- Nytt 17 sep: senaste aktivitet och om tråden är levande, så CRM-kortet kan
      -- visa att ett samtal pågår utan att fråga databasen en gång per kort.
      'ce_last_message_at', l.last_message_at,
      'ce_human_active', l.human_active,
      'ce_form', (select qualification->'form' from ce_leads where id = l.id)
    ))
  )
  on conflict (dedupe_key) where dedupe_key is not null do update set
    name = excluded.name, email = excluded.email, phone = excluded.phone,
    status = excluded.status, tags = excluded.tags,
    custom = coalesce(contacts.custom, '{}'::jsonb) || excluded.custom,
    updated_at = now()
  returning id into v_contact;

  if v_contact is null then select id into v_contact from contacts where dedupe_key = v_nyckel; end if;

  if v_contact is not null then
    v_titel := coalesce(nullif(l.name,''), 'Okänt namn')
               || case when l.days is not null then ' · ' || l.days || ' dagar' else '' end;

    if exists (select 1 from opportunities where contact_id = v_contact and pipeline_id = v_pipeline) then
      update opportunities set stage_id = v_stage, title = v_titel,
        status = case when l.status='booked' then 'won'
                      when l.status in ('cold','lost','opted_out') then 'lost' else 'open' end,
        updated_at = now()
      where contact_id = v_contact and pipeline_id = v_pipeline
        and (stage_id is distinct from v_stage or title is distinct from v_titel);
    else
      insert into opportunities (contact_id, pipeline_id, stage_id, customer_id, tenant_id, title, status)
      values (v_contact, v_pipeline, v_stage, v_customer, l.tenant_id, v_titel,
              case when l.status='booked' then 'won'
                   when l.status in ('cold','lost','opted_out') then 'lost' else 'open' end);
    end if;
  end if;

  perform set_config('ce.mirroring', v_forra, true);
end $function$;
